// app/blog/[slug]/page.js — generateMetadata quyết định <title> và mô tả (SEO)
async function generateMetadata({ params }) {
  const { slug } = await params;
  const title = slug.replace(/-/g, " ");
  return {
    title: title.charAt(0).toUpperCase() + title.slice(1) + " | Lexi Blog",
    description: "Bài viết: " + title,
  };
}

generateMetadata({ params: Promise.resolve({ slug: "hoc-next-js" }) }).then((m) =>
  console.log(JSON.stringify(m))
);

